"""Runs once a night and counts the day's payments that match no order."""


class ReconciliationWorker:
    def __init__(self, store):
        self.store = store

    def run(self, day):
        """Return how many of the day's payments match no order.

        A bank retry arrives with the same payment id, so each id counts once.
        """
        order_ids = self.store.order_ids()
        payments = {payment["id"]: payment for payment in self.store.payments(day)}
        unmatched = [payment for payment in payments.values() if payment["order_id"] not in order_ids]
        return len(unmatched)
